// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(1000);
        // Deploy address is the Log contract (this test contract), give it a balance of 10 ether
        vm.deal(address(this), 10 ether);
        // No need to deal the contract itself; Log contract doesn't need ether
        // Actor address
        address alice = address(0x1234);
        vm.deal(alice, 5 ether);
        // Alice deposits 2 ether with unlockTime = 2000 (future)
        vm.prank(alice);
        c.Put{value: 2 ether}(2000);
        // Alice tries to collect 1 ether — should revert because not past unlockTime
        // We catch the revert
        bool ok;
        vm.prank(alice);
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // In reference contract, Collect reverts -> ok = false
        // In buggy contract, Collect does not revert because balance is subtracted even when condition fails? Actually condition still checks block.timestamp > unlockTime, which is false. So Collect reverts in both? Wait — the bug is only in the balance update line inside Put. The condition in Collect is unchanged. So if condition fails, revert happens in both. Hmm.
        // Actually both revert here. Let's re-evaluate: the difference must be observable after a successful Collect. So we need to warp past unlockTime.
        // Let's do: deposit with unlockTime = 1000 (current time) so it's immediately unlocked.
        // Set block.timestamp = 1000
        vm.warp(1000);
        vm.deal(alice, 5 ether);
        // Alice deposits 2 ether with unlockTime = 1000 (<= current time, so unlockTime becomes block.timestamp = 1000)
        vm.prank(alice);
        c.Put{value: 2 ether}(1000);
        // Now warp to 2000 (past unlockTime)
        vm.warp(2000);
        // Alice calls Collect(1 ether) — should succeed in both
        vm.prank(alice);
        c.Collect(1 ether);
        // Now read public state: c.MinSum() is 1 ether; c.Acc(alice) returns (unlockTime, balance)
        // In reference, balance after Collect = 2 ether - 1 ether = 1 ether
        // In bug, Put had subtracted instead of added: after Put with 2 ether, balance became 0 - 2 = -2 (underflow? require checks acc.balance + msg.value >= acc.balance, which passes. Then acc.balance -= msg.value: 0 - 2 = uint256 underflow? Actually using unchecked? In Solidity 0.8.0, arithmetic is checked by default, so subtraction would revert on underflow. But the require ensures acc.balance + msg.value >= acc.balance, which is true even if acc.balance becomes negative? Wait, acc.balance is uint, so before subtraction, acc.balance is 0, then acc.balance -= msg.value would revert. So the buggy Put would revert on first deposit? Let's check: first deposit for alice: acc.balance = 0 initially. require(0 + 2e18 >= 0) true. Then acc.balance -= 2e18 -> underflow revert. So buggy contract would never allow a deposit. Thus after setUp, c is deployed, but any call to Put() reverts immediately. So the reference works, buggy does not. So we can test that after attempting to call Put, the balance of the contract is 0 (reference would have 2 ether, buggy reverts so 0). But the instruction says "the original contract satisfies and a given modified version breaks" — here reference passes, buggy fails on Put itself.
        // However we need to observe after Collect call. But if Put reverts, we never get to Collect. That is okay: we can assert that after attempting to Put, address(c).balance is 0 for buggy (because revert) vs 2 ether for reference? But reference Put doesn't revert, so address(c).balance = 2 ether. However we cannot catch a revert and then continue with Collect. So we need a scenario where Put succeeds but Collect behaves differently.
        // The bug changes Put's addition to subtraction. That means if balance is already > 0, a second deposit would subtract instead of add. For a first deposit, it underflows. So we need an initial deposit from another user? But mapping is per address. So for a given address, the first deposit always underflows. So no address can ever have positive balance in buggy contract. Therefore any attempt to collect will fail because balance < MinSum (1 ether). In reference, a deposit works.
        // So the simplest witness: deploy, then a user tries to deposit 2 ether. In reference, it succeeds (balance becomes 2). In buggy, it reverts. We can catch that revert and assert that the reference call succeeds (no revert) and the buggy reverts.
        // But we have only one test contract per run. We cannot compare two contracts in one test. The test is meant to be run against either reference or buggy version (by swapping the file). So we write a test that passes on reference and fails on buggy.
        // So: call Put with value. In reference, it succeeds -> no revert, we can then check that address(c).balance == 2 ether. In buggy, it reverts -> we can catch and assert false. But the assertion must be a single fact at the end. We can do: try { c.Put{value: 2 ether}(1000); ok = true; } catch { ok = false; } Then assertTrue(ok). That passes on reference (ok true) and fails on buggy (ok false). That is the simplest.
        bool ok;
        vm.deal(alice, 5 ether);
        vm.prank(alice);
        try c.Put{value: 2 ether}(1000) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

