pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Caller will be address(this) (the test contract)
        address caller = address(this);

        // Deal 1 ether to caller
        vm.deal(caller, 1 ether);

        // Call Put(0) with 1 ether via fallback (which calls Put(0) and sets unlockTime = block.timestamp)
        vm.prank(caller);
        (bool successPut, ) = address(c).call{value: 1 ether}("");
        require(successPut, "Put via fallback failed");

        // Warp to exactly the same timestamp (still block.timestamp, which equals unlockTime)
        vm.warp(block.timestamp);

        // Try Collect(1 ether) - reference should revert (timestamp == unlockTime, not greater)
        bool collectSucceeded;
        try c.Collect(1 ether) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // After the attempt, read caller's balance via the public getter
        (uint unlockTime, uint balance) = c.Acc(caller);
        // In reference: Collect reverts, so balance remains 1 ether
        // In bug: Collect succeeds (allows timestamp >= unlockTime), so balance becomes 0
        assertTrue(balance == 1 ether, "Balance should be 1 ether in reference (revert expected)");
    }
}

