    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.warp(1000);
        vm.prank(user);
        c.Put{value: 2 ether}(500);
        vm.warp(2000);
        vm.prank(user);
        c.Collect(1 ether);
        (uint unlockTime, uint balance) = c.Acc(user);
        assertTrue(balance == 1 ether);
    }
}

