// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 2 ether}(0);
        vm.warp(block.timestamp + 1 seconds);
        vm.prank(user);
        c.Collect(1 ether);
        (uint unlockTime, uint balance) = c.Acc(user);
        assertTrue(balance == 1 ether, "balance should be 1 ether in reference");
    }
}
